    public static class PartnerSeeder_v2
    {
        public static async Task SeedPartnersV2Async(UNOPSAppDbContext context)
        {
            // Create mapping from LiaisonOffice Name to Id (handle duplicates by taking first, filter out null names)
            var liaisonOffices = await context.LiaisonOffices.ToListAsync();
            var liaisonOfficeMapping = liaisonOffices
                .Where(lo => !string.IsNullOrEmpty(lo.Name))
                .GroupBy(lo => lo.Name)
                .ToDictionary(g => g.Key, g => g.First().Id);

            // Create mapping from PartnerTree Description to Id for Partner Categories (handle duplicates by taking first)
            var partnerCategories = await context.PartnerTrees
                .Where(pt => pt.PartnerCategoryCode != null)
                .ToListAsync();
            var partnerCategoryMapping = partnerCategories
                .GroupBy(pt => pt.Description)
                .ToDictionary(g => g.Key, g => g.First().Id);

            // Create mapping from PartnerTree Description to Id for Partner Groups (handle duplicates by taking first)
            var partnerGroups = await context.PartnerTrees
                .Where(pt => pt.PartnerGroupCode != null)
                .ToListAsync();
            var partnerGroupMapping = partnerGroups
                .GroupBy(pt => pt.Description)
                .ToDictionary(g => g.Key, g => g.First().Id);

            // Create mapping from PAOUser Name to Id (handle duplicates by taking first, filter out null names)
            var paoUsers = await context.PAOUsers
                .Select(u => new { u.Id, u.Name })
                .ToListAsync();
            var paoUserMapping = paoUsers
                .Where(u => !string.IsNullOrEmpty(u.Name))
                .GroupBy(u => u.Name)
                .ToDictionary(g => g.Key, g => g.First().Id);

            // Create mapping from OrganizationHierarchy Name to Id (handle duplicates by taking first, filter out null names)
            var orgUnits = await context.OrganizationHierarchies
                .Where(oh => oh.Type == Domain.Enums.OrganizationUnitType.OrgUnit)
                .ToListAsync();
            var orgUnitMapping = orgUnits
                .Where(oh => !string.IsNullOrEmpty(oh.Name))
                .GroupBy(oh => oh.Name)
                .ToDictionary(g => g.Key, g => g.First().Id);

            // Process partners
